import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ name, userName, userUsername, username, grade, subjects, handleLogout }) {
  const [materials, setMaterials] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [previewMaterial, setPreviewMaterial] = useState(null);

  const loggedInUsername = username || userUsername || '';
  const loggedInName = name || userName || '';
  const [liveProfile, setLiveProfile] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:8082/api/view-students')
      .then(res => {
        if (Array.isArray(res.data)) {
          const currentStudent = res.data.find(s => 
            (s.username && loggedInUsername && String(s.username).toLowerCase() === String(loggedInUsername).toLowerCase()) ||
            (s.name && loggedInName && String(s.name).toLowerCase() === String(loggedInName).toLowerCase())
          );
          if (currentStudent) setLiveProfile(currentStudent);
        }
      })
      .catch(err => console.error("Profile Sync Error:", err));
  }, [loggedInUsername, loggedInName]);

  const displayNameStr = liveProfile ? liveProfile.name : (loggedInName || 'Student');
  const displayGradeStr = liveProfile ? liveProfile.grade : (grade || 'Grade 8');
  const displaySubjectsStr = liveProfile ? liveProfile.subjects : (subjects || '');
  
  const mySubjects = displaySubjectsStr ? displaySubjectsStr.split(', ') : [];

  useEffect(() => {
    if (!displayGradeStr) return;
    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        setMaterials(all.filter(m => String(m.grade).toLowerCase() === String(displayGradeStr).toLowerCase() && mySubjects.some(sub => m.subject && m.subject.toLowerCase() === sub.toLowerCase())));
      });
    axios.get('http://localhost:8082/api/quizzes')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        setQuizzes(all.filter(q => String(q.grade).toLowerCase() === String(displayGradeStr).toLowerCase() && (q.is_enabled === 1 || q.is_enabled === true) && mySubjects.some(sub => q.subject_name && q.subject_name.toLowerCase() === sub.toLowerCase())));
      });
  }, [displayGradeStr, displaySubjectsStr]);

  const getMediaViewerComponent = (material) => {
    const path = material.file_path || '';
    if (path.includes('youtube.com') || path.includes('youtu.be')) {
      let videoId = path.includes('youtu.be/') ? path.split('youtu.be/')[1]?.split(/[?#]/)[0] : path.split('v=')[1]?.split(/[&#]/)[0];
      return <iframe src={`https://www.youtube.com/embed/${videoId}`} title={material.title} style={{ width: '100%', height: '440px', border: 'none', borderRadius: '8px' }} allowFullScreen />;
    }
    return path.toLowerCase().endsWith('.mp4') ? 
      <video src={`http://localhost:8082/${path}`} controls style={{ width: '100%', maxHeight: '440px', borderRadius: '8px' }} /> :
      <iframe src={`http://localhost:8082/${path}#toolbar=0`} title={material.title} style={{ width: '100%', height: '490px', border: 'none', borderRadius: '8px', backgroundColor: 'white' }} />;
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      <div style={styles.sidebar}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
          <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <button onClick={() => setActiveTab('dashboard')} style={styles.sidebarBtn(activeTab === 'dashboard')}>🏠 Dashboard Overview</button>
          <button onClick={() => setActiveTab('materials')} style={styles.sidebarBtn(activeTab === 'materials')}>📚 My Learning Materials</button>
          <button onClick={() => setActiveTab('exams')} style={styles.sidebarBtn(activeTab === 'exams')}>📝 My Online Exams</button>
          <button onClick={() => setActiveTab('forum')} style={styles.sidebarBtn(activeTab === 'forum')}>💬 Class Forum Space</button>
          <button onClick={() => setActiveTab('profile')} style={styles.sidebarBtn(activeTab === 'profile')}>👤 Profile Identity</button>
        </div>

        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button>
        </div>
      </div>

      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {activeTab === 'dashboard' && (
          <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '25px' }}>
            <div style={styles.welcomeBanner}>
              <h1 style={{ margin: '0 0 8px 0', fontSize: '26px' }}>Welcome back, {displayNameStr}! 🎓</h1>
              <p style={{ margin: 0, opacity: 0.9, fontSize: '14px' }}>Access your online classrooms, download handouts, and join live quizzes instantly.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
              <div style={styles.statCard('#7c3aed')}><div><p style={styles.statLabel}>Registered Grade</p><h2 style={styles.statValue}>{displayGradeStr}</h2></div><div style={styles.statIcon}>🏫</div></div>
              <div style={styles.statCard('#2563eb')}><div><p style={styles.statLabel}>Available Materials</p><h2 style={styles.statValue}>{materials.length}</h2></div><div style={styles.statIcon}>📂</div></div>
              <div style={styles.statCard('#ea580c')}><div><p style={styles.statLabel}>Active Quizzes</p><h2 style={styles.statValue}>{quizzes.length}</h2></div><div style={styles.statIcon}>✏️</div></div>
            </div>
          </div>
        )}

        {activeTab === 'materials' && (
          <div>
            <h3 style={{ color: '#1e293b', fontSize: '20px', marginBottom: '20px' }}>📚 Enrolled Materials Archive</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {materials.map((m, i) => (
                <div key={i} style={styles.materialRow}>
                  <div><h5 style={{ margin: 0, fontSize: '14px', color: '#1e293b' }}>{m.title}</h5><span style={{ fontSize: '11px', color: '#2563eb', fontWeight: 'bold' }}>{m.subject} | {m.material_type}</span></div>
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button onClick={() => setPreviewMaterial(m)} style={styles.viewBtn}>👁️ View In-App</button>
                    <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={styles.downBtn}>📥 Download</a>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'profile' && (
          <div style={{ animation: 'fadeIn 0.5s', maxWidth: '450px' }}>
            <h3 style={{ color: '#1e293b', marginBottom: '20px' }}>👤 Profile Identity</h3>
            <div style={styles.profileCard}>
              <div style={styles.avatarCircle}>{displayNameStr.charAt(0)}</div>
              <h2 style={{ margin: '15px 0 5px 0' }}>{displayNameStr}</h2>
              <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '25px' }}>Student Portal Account</p>
              <div style={styles.infoGrid}>
                <div><span style={styles.infoLabel}>Grade</span><div style={styles.infoValue}>{displayGradeStr}</div></div>
                <div><span style={styles.infoLabel}>Subjects</span><div style={styles.infoValue}>{displaySubjectsStr || 'None'}</div></div>
              </div>
            </div>
          </div>
        )}
      </div>

      {previewMaterial && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}><button onClick={() => setPreviewMaterial(null)} style={styles.closeBtn}>✕ Close</button>{getMediaViewerComponent(previewMaterial)}</div>
        </div>
      )}
    </div>
  );
}

const styles = {
  sidebar: { width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 },
  sidebarBtn: (active) => ({ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }),
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  welcomeBanner: { backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white' },
  statCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${color}`, boxShadow: '0 4px 15px rgba(0,0,0,0.01)', border: '1px solid #e2e8f0' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '12.5px', fontWeight: 'bold' },
  statValue: { fontSize: '18px', marginTop: '5px', marginBottom: 0, color: '#1e293b', fontWeight: '700' },
  statIcon: { fontSize: '24px', opacity: 0.7 },
  materialRow: { backgroundColor: 'white', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  viewBtn: { backgroundColor: '#16a34a', color: 'white', padding: '7px 14px', borderRadius: '6px', border: 'none', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' },
  downBtn: { backgroundColor: '#2563eb', color: 'white', padding: '7px 14px', borderRadius: '6px', textDecoration: 'none', fontSize: '12px', fontWeight: 'bold' },
  profileCard: { backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0', textAlign: 'center', boxShadow: '0 4px 15px rgba(0,0,0,0.02)' },
  avatarCircle: { width: '80px', height: '80px', backgroundColor: '#dcfce7', color: '#16a34a', borderRadius: '50%', margin: '0 auto', fontSize: '32px', fontWeight: 'bold', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  infoGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', textAlign: 'left' },
  infoLabel: { fontSize: '11px', color: '#64748b', textTransform: 'uppercase' },
  infoValue: { fontSize: '14px', fontWeight: 'bold', marginTop: '4px', color: '#1e293b' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 },
  modal: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', width: '80%', position: 'relative' },
  closeBtn: { position: 'absolute', top: '10px', right: '10px', background: '#fee2e2', border: 'none', color: '#b91c1c', padding: '8px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }
};
